input.command:
node -e '
const { spawn } = require("child_process");
const p = spawn("npx", ["tsx", "src/index.ts"], { stdio: ["pipe", "pipe", "pipe"] });
let buf = "";
p.stdout.on("data", d => { buf += d.toString(); });
p.stderr.on("data", d => process.stderr.write(d));

const send = (obj) => p.stdin.write(JSON.stringify(obj) + "\n");

send({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "test", version: "0.0.1" } } });

setTimeout(() => {
  send({ jsonrpc: "2.0", method: "notifications/initialized" });
  send({ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} });
}, 1000);

setTimeout(() => {
  send({ jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "add", arguments: { a: 2, b: 3 } } });
}, 2000);

setTimeout(() => {
  console.log("---OUTPUT---");
  console.log(buf);
  p.kill();
  process.exit(0);
}, 3500);
'
